const input = $json.date || $json.text || $json.query;
if (!input) return "No date was provided.";

const timezone = "Africa/Lagos";
const now = new Date();
const todayString = new Intl.DateTimeFormat("en-CA", {
  timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit"
}).format(now);
const [year, month, day] = todayString.split("-").map(Number);
const today = new Date(Date.UTC(year, month - 1, day, 12));
const weekdays = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];

function result(date) {
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return JSON.stringify({
    input,
    date: `${y}-${m}-${d}`,
    dayOfWeek: weekdays[date.getUTCDay()],
    timezone,
    isBusinessDay: date.getUTCDay() >= 1 && date.getUTCDay() <= 5
  });
}

const text = input.trim().toLowerCase();
if (text === "today") return result(today);
if (text === "tomorrow") {
  const date = new Date(today); date.setUTCDate(date.getUTCDate() + 1); return result(date);
}
if (text === "yesterday") {
  const date = new Date(today); date.setUTCDate(date.getUTCDate() - 1); return result(date);
}

const weekdaysMap = { sunday:0, monday:1, tuesday:2, wednesday:3, thursday:4, friday:5, saturday:6 };
const weekdayMatch = text.match(/^(this|next)\\s+(sunday|monday|tuesday|wednesday|thursday|friday|saturday)$/);
if (weekdayMatch) {
  const type = weekdayMatch[1], requestedDay = weekdaysMap[weekdayMatch[2]], currentDay = today.getUTCDay();
  let difference = requestedDay - currentDay;
  if (difference < 0) difference += 7;
  if (type === "next" && difference === 0) difference = 7;
  const date = new Date(today); date.setUTCDate(date.getUTCDate() + difference);
  return result(date);
}

if (weekdaysMap[text] !== undefined) {
  const requestedDay = weekdaysMap[text], currentDay = today.getUTCDay();
  let difference = requestedDay - currentDay;
  if (difference < 0) difference += 7;
  const date = new Date(today); date.setUTCDate(date.getUTCDate() + difference);
  return result(date);
}

const months = {
  january:0,february:1,march:2,april:3,may:4,june:5,july:6,
  august:7,september:8,october:9,november:10,december:11
};

let match = text.match(/^(january|february|march|april|may|june|july|august|september|october|november|december)\\s+(\\d{1,2})(?:\\s+(\\d{4}))?$/);
if (match) {
  const month = months[match[1]], dayNumber = Number(match[2]);
  let targetYear = match[3] ? Number(match[3]) : year;
  let date = new Date(Date.UTC(targetYear, month, dayNumber, 12));
  if (!match[3] && date < today) {
    targetYear++;
    date = new Date(Date.UTC(targetYear, month, dayNumber, 12));
  }
  if (date.getUTCMonth() !== month || date.getUTCDate() !== dayNumber) return "Invalid calendar date.";
  return result(date);
}

match = text.match(/^(\\d{1,2})\\s+(january|february|march|april|may|june|july|august|september|october|november|december)(?:\\s+(\\d{4}))?$/);
if (match) {
  const dayNumber = Number(match[1]), month = months[match[2]];
  let targetYear = match[3] ? Number(match[3]) : year;
  let date = new Date(Date.UTC(targetYear, month, dayNumber, 12));
  if (!match[3] && date < today) {
    targetYear++;
    date = new Date(Date.UTC(targetYear, month, dayNumber, 12));
  }
  if (date.getUTCMonth() !== month || date.getUTCDate() !== dayNumber) return "Invalid calendar date.";
  return result(date);
}

match = text.match(/^(\\d{4})-(\\d{1,2})-(\\d{1,2})$/);
if (match) {
  const targetYear = Number(match[1]), targetMonth = Number(match[2]) - 1, targetDay = Number(match[3]);
  const date = new Date(Date.UTC(targetYear, targetMonth, targetDay, 12));
  if (date.getUTCFullYear() !== targetYear || date.getUTCMonth() !== targetMonth || date.getUTCDate() !== targetDay) return "Invalid calendar date.";
  return result(date);
}

return `I could not understand the date "${input}". Please provide a date such as "tomorrow", "next Monday", "August 14", or "August 14 2026".`;
